function coveringWalks(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  let total = 0, sr = 0, sc = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    if (grid[r][c] !== -1) total++;
    if (grid[r][c] === 1) { sr = r; sc = c; }
  }
  const walk = (r: number, c: number, seen: Set<number>): number => {
    if (grid[r][c] === 2) return seen.size === total ? 1 : 0;
    let ways = 0;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= R || nc >= C || grid[nr][nc] === -1) continue;
      if (seen.has(nr * C + nc)) continue;
      const next = new Set(seen);
      next.add(nr * C + nc);
      ways += walk(nr, nc, next);
    }
    return ways;
  };
  return walk(sr, sc, new Set([sr * C + sc]));
}

