function coveringWalks(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  let open = 0, sr = 0, sc = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    if (grid[r][c] !== -1) open++;
    if (grid[r][c] === 1) { sr = r; sc = c; }
  }
  // left = unvisited cells, counting (r, c) itself
  const dfs = (r: number, c: number, left: number): number => {
    if (grid[r][c] === 2) return left === 1 ? 1 : 0;
    const saved = grid[r][c];
    grid[r][c] = -1;
    let ways = 0;
    if (r > 0 && grid[r - 1][c] !== -1) ways += dfs(r - 1, c, left - 1);
    if (r + 1 < R && grid[r + 1][c] !== -1) ways += dfs(r + 1, c, left - 1);
    if (c > 0 && grid[r][c - 1] !== -1) ways += dfs(r, c - 1, left - 1);
    if (c + 1 < C && grid[r][c + 1] !== -1) ways += dfs(r, c + 1, left - 1);
    grid[r][c] = saved;
    return ways;
  };
  return dfs(sr, sc, open);
}

